188→// BenchmarkMigrateCheckpoints simulates migrating uncompressed checkpoints to compressed format.
189→func BenchmarkMigrateCheckpoints(b *testing.B) {
190→	transcriptSize := 200 * 1024 // 200KB per transcript
191→	checkpointCount := 50
192→
193→	b.Run(fmt.Sprintf("%d_checkpoints", checkpointCount), func(b *testing.B) {
194→		transcript := generateBenchJSONL(transcriptSize)
195→
196→		repo := benchutil.NewBenchRepo(b, benchutil.RepoOpts{FileCount: 5, FileSizeLines: 10})
197→		gitRepo, err := gogit.PlainOpen(repo.Dir)
198→		if err != nil {
199→			b.Fatal(err)
200→		}
201→
202→		// Create uncompressed blobs (simulating old format)
203→		var blobHashes []plumbing.Hash
204→		for range checkpointCount {
205→			hash, blobErr := checkpoint.CreateBlobFromContent(gitRepo, transcript)
206→			if blobErr != nil {
207→				b.Fatal(blobErr)
208→			}
209→			blobHashes = append(blobHashes, hash)
210→		}
211→
212→		b.SetBytes(int64(checkpointCount) * int64(len(transcript)))
213→		b.ResetTimer()
214→
215→		for b.Loop() {
216→			// Simulate: read each blob, compress, write new blob
217→			for _, hash := range blobHashes {
218→				blob, blobErr := gitRepo.BlobObject(hash)
219→				if blobErr != nil {
220→					b.Fatal(blobErr)
221→				}
222→				reader, readErr := blob.Reader()
223→				if readErr != nil {
224→					b.Fatal(readErr)
225→				}
226→				content := make([]byte, blob.Size)
227→				if _, readContentErr := reader.Read(content); readContentErr != nil {
228→					b.Fatal(readContentErr)
229→				}
230→				_ = reader.Close()
231→
232→				compressed, compressErr := compression.Compress(content)
233→				if compressErr != nil {
234→					b.Fatal(compressErr)
235→				}
236→				_, blobErr = checkpoint.CreateBlobFromContent(gitRepo, compressed)
237→				if blobErr != nil {
238→					b.Fatal(blobErr)
239→				}
240→			}
241→		}
242→	})
243→}
