 37→    37→    37→var errStopIteration = errors.New("stop iteration")
 38→    38→    38→
 39→    39→    39→// WriteCommitted writes a committed checkpoint to the entire/checkpoints/v1 branch.
 40→    40→    40→// Checkpoints are stored at sharded paths: <id[:2]>/<id[2:]>/
 41→    41→    41→//
 42→    42→    42→// For task checkpoints (IsTask=true), additional files are written under tasks/<tool-use-id>/:
 43→    43→    43→//   - For incremental checkpoints: checkpoints/NNN-<tool-use-id>.json
 44→    44→    44→//   - For final checkpoints: checkpoint.json and agent-<agent-id>.jsonl
 45→    45→    45→func (s *GitStore) WriteCommitted(ctx context.Context, opts WriteCommittedOptions) error {
 46→    46→    46→	_ = ctx // Reserved for future use
 47→    47→    47→
 48→    48→    48→	// Validate identifiers to prevent path traversal and malformed data
 49→    49→    49→	if opts.CheckpointID.IsEmpty() {
 50→    50→    50→		return errors.New("invalid checkpoint options: checkpoint ID is required")
 51→    51→    51→	}
 52→    52→    52→	if err := validation.ValidateSessionID(opts.SessionID); err != nil {
 53→    53→    53→		return fmt.Errorf("invalid checkpoint options: %w", err)
 54→    54→    54→	}
 55→    55→    55→	if err := validation.ValidateToolUseID(opts.ToolUseID); err != nil {
 56→    56→    56→		return fmt.Errorf("invalid checkpoint options: %w", err)
 57→    57→    57→	}
 58→    58→    58→	if err := validation.ValidateAgentID(opts.AgentID); err != nil {
 59→    59→    59→		return fmt.Errorf("invalid checkpoint options: %w", err)
 60→    60→    60→	}
 61→    61→    61→
 62→    62→    62→	// Ensure sessions branch exists
 63→    63→    63→	if err := s.ensureSessionsBranch(); err != nil {
 64→    64→    64→		return fmt.Errorf("failed to ensure sessions branch: %w", err)
 65→    65→    65→	}
 66→    66→    66→
 67→    67→    67→	// Get branch ref and root tree hash (O(1), no flatten)
 68→    68→    68→	parentHash, rootTreeHash, err := s.getSessionsBranchRef()
 69→    69→    69→	if err != nil {
 70→    70→    70→		return err
 71→    71→    71→	}
 72→    72→    72→
 73→    73→    73→	// Use sharded path: <id[:2]>/<id[2:]>/
 74→    74→    74→	basePath := opts.CheckpointID.Path() + "/"
 75→    75→    75→	checkpointPath := opts.CheckpointID.Path()
 76→    76→    76→
 77→    77→    77→	// Flatten only the checkpoint subtree (O(files in checkpoint))
 78→    78→    78→	entries, err := s.flattenCheckpointEntries(rootTreeHash, checkpointPath)
 79→    79→    79→	if err != nil {
 80→    80→    80→		return err
 81→    81→    81→	}
 82→    82→    82→
 83→    83→    83→	// Track task metadata path for commit trailer
 84→    84→    84→	var taskMetadataPath string
 85→    85→    85→
 86→    86→    86→	// Handle task checkpoints
 87→    87→    87→	if opts.IsTask && opts.ToolUseID != "" {
 88→    88→    88→		taskMetadataPath, err = s.writeTaskCheckpointEntries(opts, basePath, entries)
 89→    89→    89→		if err != nil {
 90→    90→    90→			return err
 91→    91→    91→		}
 92→    92→    92→	}
 93→    93→    93→
 94→    94→    94→	// Write standard checkpoint entries (transcript, prompts, context, metadata)
 95→    95→    95→	if err := s.writeStandardCheckpointEntries(opts, basePath, entries); err != nil {
 96→    96→    96→		return err
 97→    97→    97→	}
 98→    98→    98→
 99→    99→    99→	// Build checkpoint subtree and splice into root (O(depth) tree surgery)
100→   100→   100→	newTreeHash, err := s.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
101→   101→   101→	if err != nil {
102→   102→   102→		return err
103→   103→   103→	}
104→   104→   104→
105→   105→   105→	commitMsg := s.buildCommitMessage(opts, taskMetadataPath)
106→   106→   106→	newCommitHash, err := s.createCommit(newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail)
107→   107→   107→	if err != nil {
108→   108→   108→		return err
109→   109→   109→	}
110→   110→   110→
111→   111→   111→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
112→   112→   112→	newRef := plumbing.NewHashReference(refName, newCommitHash)
113→   113→   113→	if err := s.repo.Storer.SetReference(newRef); err != nil {
114→   114→   114→		return fmt.Errorf("failed to set branch reference: %w", err)
115→   115→   115→	}
116→   116→   116→
117→   117→   117→	return nil
118→   118→   118→}
119→   119→   119→
120→   120→   120→// flattenCheckpointEntries reads only the entries under a specific checkpoint path
121→   121→   121→// from the sessions branch tree. This is O(files in checkpoint) instead of O(all checkpoints).
122→   122→   122→// Returns an empty map if the checkpoint doesn't exist yet.
123→   123→   123→func (s *GitStore) flattenCheckpointEntries(rootTreeHash plumbing.Hash, checkpointPath string) (map[string]object.TreeEntry, error) {
124→   124→   124→	entries := make(map[string]object.TreeEntry)
125→   125→   125→	if rootTreeHash == plumbing.ZeroHash {
126→   126→   126→		return entries, nil
127→   127→   127→	}
128→   128→   128→
129→   129→   129→	rootTree, err := s.repo.TreeObject(rootTreeHash)
130→   130→   130→	if err != nil {
131→   131→   131→		if errors.Is(err, plumbing.ErrObjectNotFound) {
132→   132→   132→			return entries, nil // Tree doesn't exist yet
133→   133→   133→		}
134→   134→   134→		return nil, fmt.Errorf("failed to read root tree %s: %w", rootTreeHash, err)
135→   135→   135→	}
136→   136→   136→
137→   137→   137→	subtree, err := rootTree.Tree(checkpointPath)
138→   138→   138→	if err != nil {
139→   139→   139→		return entries, nil //nolint:nilerr // Checkpoint doesn't exist yet
140→   140→   140→	}
141→   141→   141→
142→   142→   142→	// Flatten just this subtree with the full path prefix
143→   143→   143→	if err := FlattenTree(s.repo, subtree, checkpointPath, entries); err != nil {
144→   144→   144→		return nil, err
145→   145→   145→	}
146→   146→   146→	return entries, nil
147→   147→   147→}
148→   148→   148→
149→   149→   149→// spliceCheckpointSubtree builds a tree from checkpoint-local entries and installs it
150→   150→   150→// at the correct shard location in the root tree using O(depth) tree surgery.
151→   151→   151→// basePath is like "a3/b2c4d5e6f7/" (with trailing slash).
152→   152→   152→// Returns the new root tree hash.
153→   153→   153→func (s *GitStore) spliceCheckpointSubtree(rootTreeHash plumbing.Hash, checkpointID id.CheckpointID, basePath string, entries map[string]object.TreeEntry) (plumbing.Hash, error) {
154→   154→   154→	// Convert entries to relative paths (strip basePath prefix)
155→   155→   155→	relEntries := make(map[string]object.TreeEntry, len(entries))
156→   156→   156→	for path, entry := range entries {
157→   157→   157→		relPath := strings.TrimPrefix(path, basePath)
158→   158→   158→		if relPath == path {
159→   159→   159→			continue // Entry doesn't have the expected prefix
160→   160→   160→		}
161→   161→   161→		relEntries[relPath] = entry
162→   162→   162→	}
163→   163→   163→
164→   164→   164→	// Build the checkpoint subtree from relative entries
165→   165→   165→	checkpointTreeHash, err := BuildTreeFromEntries(s.repo, relEntries)
166→   166→   166→	if err != nil {
167→   167→   167→		return plumbing.ZeroHash, fmt.Errorf("failed to build checkpoint subtree: %w", err)
168→   168→   168→	}
169→   169→   169→
170→   170→   170→	// Splice into root tree at the shard path using tree surgery
171→   171→   171→	// Path: ["a3"] with entry "b2c4d5e6f7" pointing to the checkpoint tree
172→   172→   172→	shardPrefix := string(checkpointID[:2])
173→   173→   173→	shardSuffix := string(checkpointID[2:])
174→   174→   174→	return UpdateSubtree(s.repo, rootTreeHash, []string{shardPrefix}, []object.TreeEntry{
175→   175→   175→		{Name: shardSuffix, Mode: filemode.Dir, Hash: checkpointTreeHash},
176→   176→   176→	}, UpdateSubtreeOptions{MergeMode: MergeKeepExisting})
177→   177→   177→}
