190→   190→   190→func (s *GitStore) writeIncrementalTaskCheckpoint(opts WriteCommittedOptions, taskPath string, entries map[string]object.TreeEntry) (string, error) {
191→   191→   191→	incData, err := redact.JSONLBytes(opts.IncrementalData)
192→   192→   192→	if err != nil {
193→   193→   193→		return "", fmt.Errorf("failed to redact incremental checkpoint: %w", err)
194→   194→   194→	}
195→   195→   195→	checkpoint := incrementalCheckpointData{
196→   196→   196→		Type:      opts.IncrementalType,
197→   197→   197→		ToolUseID: opts.ToolUseID,
198→   198→   198→		Timestamp: time.Now().UTC(),
199→   199→   199→		Data:      incData,
200→   200→   200→	}
201→   201→   201→	cpData, err := jsonutil.MarshalIndentWithNewline(checkpoint, "", "  ")
202→   202→   202→	if err != nil {
203→   203→   203→		return "", fmt.Errorf("failed to marshal incremental checkpoint: %w", err)
204→   204→   204→	}
205→   205→   205→	cpBlobHash, err := CreateBlobFromContent(s.repo, cpData)
206→   206→   206→	if err != nil {
207→   207→   207→		return "", fmt.Errorf("failed to create incremental checkpoint blob: %w", err)
208→   208→   208→	}
209→   209→   209→
210→   210→   210→	cpFilename := fmt.Sprintf("%03d-%s.json", opts.IncrementalSequence, opts.ToolUseID)
211→   211→   211→	cpPath := taskPath + "checkpoints/" + cpFilename
212→   212→   212→	entries[cpPath] = object.TreeEntry{
213→   213→   213→		Name: cpPath,
214→   214→   214→		Mode: filemode.Regular,
215→   215→   215→		Hash: cpBlobHash,
216→   216→   216→	}
217→   217→   217→	return cpPath, nil
218→   218→   218→}
