220→   220→   220→// writeFinalTaskCheckpoint writes the final checkpoint.json and subagent transcript.
221→   221→   221→func (s *GitStore) writeFinalTaskCheckpoint(opts WriteCommittedOptions, taskPath string, entries map[string]object.TreeEntry) (string, error) {
222→   222→   222→	checkpoint := taskCheckpointData{
223→   223→   223→		SessionID:      opts.SessionID,
224→   224→   224→		ToolUseID:      opts.ToolUseID,
225→   225→   225→		CheckpointUUID: opts.CheckpointUUID,
226→   226→   226→		AgentID:        opts.AgentID,
227→   227→   227→	}
228→   228→   228→	checkpointData, err := jsonutil.MarshalIndentWithNewline(checkpoint, "", "  ")
229→   229→   229→	if err != nil {
230→   230→   230→		return "", fmt.Errorf("failed to marshal task checkpoint: %w", err)
231→   231→   231→	}
232→   232→   232→	blobHash, err := CreateBlobFromContent(s.repo, checkpointData)
233→   233→   233→	if err != nil {
234→   234→   234→		return "", fmt.Errorf("failed to create task checkpoint blob: %w", err)
235→   235→   235→	}
236→   236→   236→
237→   237→   237→	checkpointFile := taskPath + "checkpoint.json"
238→   238→   238→	entries[checkpointFile] = object.TreeEntry{
239→   239→   239→		Name: checkpointFile,
240→   240→   240→		Mode: filemode.Regular,
241→   241→   241→		Hash: blobHash,
242→   242→   242→	}
243→   243→   243→
244→   244→   244→	// Write subagent transcript if available
245→   245→   245→	if opts.SubagentTranscriptPath != "" && opts.AgentID != "" {
246→   246→   246→		agentContent, readErr := os.ReadFile(opts.SubagentTranscriptPath)
247→   247→   247→		if readErr == nil {
248→   248→   248→			// Try JSONL-aware redaction first; fall back to plain string redaction
249→   249→   249→			// if the content is not valid JSONL (avoids silently dropping the transcript).
250→   250→   250→			redacted, jsonlErr := redact.JSONLBytes(agentContent)
251→   251→   251→			if jsonlErr != nil {
252→   252→   252→				logging.Warn(context.Background(), "subagent transcript is not valid JSONL, falling back to plain redaction",
253→   253→   253→					slog.String("path", opts.SubagentTranscriptPath),
254→   254→   254→					slog.String("error", jsonlErr.Error()),
255→   255→   255→				)
256→   256→   256→				redacted = redact.Bytes(agentContent)
257→   257→   257→			}
258→   258→   258→			agentContent = redacted
259→   259→   259→
260→   260→   260→			agentBlobHash, agentBlobErr := CreateBlobFromContent(s.repo, agentContent)
261→   261→   261→			if agentBlobErr == nil {
262→   262→   262→				agentPath := taskPath + "agent-" + opts.AgentID + ".jsonl"
263→   263→   263→				entries[agentPath] = object.TreeEntry{
264→   264→   264→					Name: agentPath,
265→   265→   265→					Mode: filemode.Regular,
266→   266→   266→					Hash: agentBlobHash,
267→   267→   267→				}
268→   268→   268→			}
269→   269→   269→		}
270→   270→   270→	}
271→   271→   271→
272→   272→   272→	// Return task path without trailing slash
273→   273→   273→	return taskPath[:len(taskPath)-1], nil
274→   274→   274→}
