276→   276→   276→// writeStandardCheckpointEntries writes session files to numbered subdirectories and
277→   277→   277→// maintains a CheckpointSummary at the root level with aggregated statistics.
278→   278→   278→//
279→   279→   279→// Structure:
280→   280→   280→//
281→   281→   281→//	basePath/
282→   282→   282→//	├── metadata.json         # CheckpointSummary (aggregated stats)
283→   283→   283→//	├── 1/                    # First session
284→   284→   284→//	│   ├── metadata.json     # CommittedMetadata (session-specific, includes initial_attribution)
285→   285→   285→//	│   ├── full.jsonl
286→   286→   286→//	│   ├── prompt.txt
287→   287→   287→//	│   ├── context.md
288→   288→   288→//	│   └── content_hash.txt
289→   289→   289→//	├── 2/                    # Second session
290→   290→   290→//	└── ...
291→   291→   291→func (s *GitStore) writeStandardCheckpointEntries(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
292→   292→   292→	// Read existing summary to get current session count
293→   293→   293→	var existingSummary *CheckpointSummary
294→   294→   294→	metadataPath := basePath + paths.MetadataFileName
295→   295→   295→	if entry, exists := entries[metadataPath]; exists {
296→   296→   296→		existing, err := s.readSummaryFromBlob(entry.Hash)
297→   297→   297→		if err == nil {
298→   298→   298→			existingSummary = existing
299→   299→   299→		}
300→   300→   300→	}
301→   301→   301→
302→   302→   302→	// Determine session index: reuse existing slot if session ID matches, otherwise append
303→   303→   303→	sessionIndex := s.findSessionIndex(basePath, existingSummary, entries, opts.SessionID)
304→   304→   304→
305→   305→   305→	// Write session files to numbered subdirectory
306→   306→   306→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
307→   307→   307→	sessionFilePaths, err := s.writeSessionToSubdirectory(opts, sessionPath, entries)
308→   308→   308→	if err != nil {
309→   309→   309→		return err
310→   310→   310→	}
311→   311→   311→
312→   312→   312→	// Copy additional metadata files from directory if specified (to session subdirectory)
313→   313→   313→	if opts.MetadataDir != "" {
314→   314→   314→		if err := s.copyMetadataDir(opts.MetadataDir, sessionPath, entries); err != nil {
315→   315→   315→			return fmt.Errorf("failed to copy metadata directory: %w", err)
316→   316→   316→		}
317→   317→   317→	}
318→   318→   318→
319→   319→   319→	// Build the sessions array
320→   320→   320→	var sessions []SessionFilePaths
321→   321→   321→	if existingSummary != nil {
322→   322→   322→		sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
323→   323→   323→		copy(sessions, existingSummary.Sessions)
324→   324→   324→	} else {
325→   325→   325→		sessions = make([]SessionFilePaths, 1)
326→   326→   326→	}
327→   327→   327→	sessions[sessionIndex] = sessionFilePaths
328→   328→   328→
329→   329→   329→	// Update root metadata.json with CheckpointSummary
330→   330→   330→	return s.writeCheckpointSummary(opts, basePath, entries, sessions)
331→   331→   331→}
