333→   333→   333→// writeSessionToSubdirectory writes a single session's files to a numbered subdirectory.
334→   334→   334→// Returns the absolute file paths from the git tree root for the sessions map.
335→   335→   335→func (s *GitStore) writeSessionToSubdirectory(opts WriteCommittedOptions, sessionPath string, entries map[string]object.TreeEntry) (SessionFilePaths, error) {
336→   336→   336→	filePaths := SessionFilePaths{}
337→   337→   337→
338→   338→   338→	// Clear any existing entries at this path so stale files from a previous
339→   339→   339→	// write (e.g. prompt.txt, context.md) don't persist on overwrite.
340→   340→   340→	for key := range entries {
341→   341→   341→		if strings.HasPrefix(key, sessionPath) {
342→   342→   342→			delete(entries, key)
343→   343→   343→		}
344→   344→   344→	}
345→   345→   345→
346→   346→   346→	// Write transcript
347→   347→   347→	if err := s.writeTranscript(opts, sessionPath, entries); err != nil {
348→   348→   348→		return filePaths, err
349→   349→   349→	}
350→   350→   350→	filePaths.Transcript = "/" + sessionPath + paths.TranscriptFileName
351→   351→   351→	filePaths.ContentHash = "/" + sessionPath + paths.ContentHashFileName
352→   352→   352→
353→   353→   353→	// Write prompts
354→   354→   354→	if len(opts.Prompts) > 0 {
355→   355→   355→		promptContent := redact.String(strings.Join(opts.Prompts, "\n\n---\n\n"))
356→   356→   356→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
357→   357→   357→		if err != nil {
358→   358→   358→			return filePaths, err
359→   359→   359→		}
360→   360→   360→		entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
361→   361→   361→			Name: sessionPath + paths.PromptFileName,
362→   362→   362→			Mode: filemode.Regular,
363→   363→   363→			Hash: blobHash,
364→   364→   364→		}
365→   365→   365→		filePaths.Prompt = "/" + sessionPath + paths.PromptFileName
366→   366→   366→	}
367→   367→   367→
368→   368→   368→	// Write context
369→   369→   369→	if len(opts.Context) > 0 {
370→   370→   370→		blobHash, err := CreateBlobFromContent(s.repo, redact.Bytes(opts.Context))
371→   371→   371→		if err != nil {
372→   372→   372→			return filePaths, err
373→   373→   373→		}
374→   374→   374→		entries[sessionPath+paths.ContextFileName] = object.TreeEntry{
375→   375→   375→			Name: sessionPath + paths.ContextFileName,
376→   376→   376→			Mode: filemode.Regular,
377→   377→   377→			Hash: blobHash,
378→   378→   378→		}
379→   379→   379→		filePaths.Context = "/" + sessionPath + paths.ContextFileName
380→   380→   380→	}
381→   381→   381→
382→   382→   382→	// Write session-level metadata.json (CommittedMetadata with all fields including initial_attribution)
383→   383→   383→	sessionMetadata := CommittedMetadata{
384→   384→   384→		CheckpointID:                opts.CheckpointID,
385→   385→   385→		SessionID:                   opts.SessionID,
386→   386→   386→		Strategy:                    opts.Strategy,
387→   387→   387→		CreatedAt:                   time.Now().UTC(),
388→   388→   388→		Branch:                      opts.Branch,
389→   389→   389→		CheckpointsCount:            opts.CheckpointsCount,
390→   390→   390→		FilesTouched:                opts.FilesTouched,
391→   391→   391→		Agent:                       opts.Agent,
392→   392→   392→		TurnID:                      opts.TurnID,
393→   393→   393→		IsTask:                      opts.IsTask,
394→   394→   394→		ToolUseID:                   opts.ToolUseID,
395→   395→   395→		TranscriptIdentifierAtStart: opts.TranscriptIdentifierAtStart,
396→   396→   396→		CheckpointTranscriptStart:   opts.CheckpointTranscriptStart,
397→   397→   397→		TranscriptLinesAtStart:      opts.CheckpointTranscriptStart, // Deprecated: kept for backward compat
398→   398→   398→		TokenUsage:                  opts.TokenUsage,
399→   399→   399→		InitialAttribution:          opts.InitialAttribution,
400→   400→   400→		Summary:                     redactSummary(opts.Summary),
401→   401→   401→		CLIVersion:                  versioninfo.Version,
402→   402→   402→	}
403→   403→   403→
404→   404→   404→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(sessionMetadata, "", "  ")
405→   405→   405→	if err != nil {
406→   406→   406→		return filePaths, fmt.Errorf("failed to marshal session metadata: %w", err)
407→   407→   407→	}
408→   408→   408→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
409→   409→   409→	if err != nil {
410→   410→   410→		return filePaths, err
411→   411→   411→	}
412→   412→   412→	entries[sessionPath+paths.MetadataFileName] = object.TreeEntry{
413→   413→   413→		Name: sessionPath + paths.MetadataFileName,
414→   414→   414→		Mode: filemode.Regular,
415→   415→   415→		Hash: metadataHash,
416→   416→   416→	}
417→   417→   417→	filePaths.Metadata = "/" + sessionPath + paths.MetadataFileName
418→   418→   418→
419→   419→   419→	return filePaths, nil
420→   420→   420→}
