422→   422→   422→// writeCheckpointSummary writes the root-level CheckpointSummary with aggregated statistics.
423→   423→   423→// sessions is the complete sessions array (already built by the caller).
424→   424→   424→func (s *GitStore) writeCheckpointSummary(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry, sessions []SessionFilePaths) error {
425→   425→   425→	checkpointsCount, filesTouched, tokenUsage, err :=
426→   426→   426→		s.reaggregateFromEntries(basePath, len(sessions), entries)
427→   427→   427→	if err != nil {
428→   428→   428→		return fmt.Errorf("failed to aggregate session stats: %w", err)
429→   429→   429→	}
430→   430→   430→
431→   431→   431→	summary := CheckpointSummary{
432→   432→   432→		CheckpointID:     opts.CheckpointID,
433→   433→   433→		CLIVersion:       versioninfo.Version,
434→   434→   434→		Strategy:         opts.Strategy,
435→   435→   435→		Branch:           opts.Branch,
436→   436→   436→		CheckpointsCount: checkpointsCount,
437→   437→   437→		FilesTouched:     filesTouched,
438→   438→   438→		Sessions:         sessions,
439→   439→   439→		TokenUsage:       tokenUsage,
440→   440→   440→	}
441→   441→   441→
442→   442→   442→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
443→   443→   443→	if err != nil {
444→   444→   444→		return fmt.Errorf("failed to marshal checkpoint summary: %w", err)
445→   445→   445→	}
446→   446→   446→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
447→   447→   447→	if err != nil {
448→   448→   448→		return err
449→   449→   449→	}
450→   450→   450→	entries[basePath+paths.MetadataFileName] = object.TreeEntry{
451→   451→   451→		Name: basePath + paths.MetadataFileName,
452→   452→   452→		Mode: filemode.Regular,
453→   453→   453→		Hash: metadataHash,
454→   454→   454→	}
455→   455→   455→	return nil
456→   456→   456→}
