458→   458→   458→// findSessionIndex returns the index of an existing session with the given ID,
459→   459→   459→// or the next available index if not found. This prevents duplicate session entries.
460→   460→   460→func (s *GitStore) findSessionIndex(basePath string, existingSummary *CheckpointSummary, entries map[string]object.TreeEntry, sessionID string) int {
461→   461→   461→	if existingSummary == nil {
462→   462→   462→		return 0
463→   463→   463→	}
464→   464→   464→	for i := range len(existingSummary.Sessions) {
465→   465→   465→		path := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
466→   466→   466→		if entry, exists := entries[path]; exists {
467→   467→   467→			meta, err := s.readMetadataFromBlob(entry.Hash)
468→   468→   468→			if err != nil {
469→   469→   469→				logging.Warn(context.Background(), "failed to read session metadata during dedup check",
470→   470→   470→					slog.Int("session_index", i),
471→   471→   471→					slog.String("session_id", sessionID),
472→   472→   472→					slog.String("error", err.Error()),
473→   473→   473→				)
474→   474→   474→				continue
475→   475→   475→			}
476→   476→   476→			if meta.SessionID == sessionID {
477→   477→   477→				return i
478→   478→   478→			}
479→   479→   479→		}
480→   480→   480→	}
481→   481→   481→	return len(existingSummary.Sessions)
482→   482→   482→}
