484→   484→   484→// reaggregateFromEntries reads all session metadata from the entries map and
485→   485→   485→// reaggregates CheckpointsCount, FilesTouched, and TokenUsage.
486→   486→   486→func (s *GitStore) reaggregateFromEntries(basePath string, sessionCount int, entries map[string]object.TreeEntry) (int, []string, *agent.TokenUsage, error) {
487→   487→   487→	var totalCount int
488→   488→   488→	var allFiles []string
489→   489→   489→	var totalTokens *agent.TokenUsage
490→   490→   490→
491→   491→   491→	for i := range sessionCount {
492→   492→   492→		path := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
493→   493→   493→		entry, exists := entries[path]
494→   494→   494→		if !exists {
495→   495→   495→			return 0, nil, nil, fmt.Errorf("session %d metadata not found at %s", i, path)
496→   496→   496→		}
497→   497→   497→		meta, err := s.readMetadataFromBlob(entry.Hash)
498→   498→   498→		if err != nil {
499→   499→   499→			return 0, nil, nil, fmt.Errorf("failed to read session %d metadata: %w", i, err)
500→   500→   500→		}

