 17→)
 18→
 19→// --- WriteTemporary benchmarks ---
 20→// WriteTemporary is the hot path that fires on every agent turn (SaveStep).
 21→// It builds a git tree from changed files and commits to the shadow branch.
 22→
 23→func BenchmarkWriteTemporary(b *testing.B) {
 24→	b.Run("FirstCheckpoint_SmallRepo", benchWriteTemporaryFirstCheckpoint(10, 100))
 25→	b.Run("FirstCheckpoint_LargeRepo", benchWriteTemporaryFirstCheckpoint(50, 500))
 26→	b.Run("Incremental_FewFiles", benchWriteTemporaryIncremental(3, 0, 0))
 27→	b.Run("Incremental_ManyFiles", benchWriteTemporaryIncremental(30, 10, 5))
 28→	b.Run("Incremental_LargeFiles", benchWriteTemporaryIncrementalLargeFiles(2, 10000))
 29→	b.Run("Dedup_NoChanges", benchWriteTemporaryDedup())
 30→	b.Run("ManyPriorCheckpoints", benchWriteTemporaryWithHistory(50))
 31→}
 32→
 33→// benchWriteTemporaryFirstCheckpoint benchmarks the first checkpoint of a session.
 34→// The first checkpoint captures all changed files via `git status`, which is heavier
 35→// than incremental checkpoints.
 36→func benchWriteTemporaryFirstCheckpoint(fileCount, fileSizeLines int) func(*testing.B) {
 37→	return func(b *testing.B) {
 38→		repo := benchutil.NewBenchRepo(b, benchutil.RepoOpts{
 39→			FileCount:     fileCount,
 40→			FileSizeLines: fileSizeLines,
 41→		})
 42→		sessionID := repo.CreateSessionState(b, benchutil.SessionOpts{})
 43→
 44→		// Modify a few files to create a dirty working directory
 45→		for i := range 3 {
 46→			name := fmt.Sprintf("src/file_%03d.go", i)
 47→			repo.WriteFile(b, name, benchutil.GenerateGoFile(9000+i, fileSizeLines))
 48→		}
 49→
 50→		metadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
 51→		metadataDirAbs := filepath.Join(repo.Dir, metadataDir)
 52→		if err := os.MkdirAll(metadataDirAbs, 0o750); err != nil {
 53→			b.Fatalf("mkdir metadata: %v", err)
 54→		}
 55→
 56→		// WriteTemporary uses paths.WorktreeRoot() which requires cwd to be in the repo.
 57→		b.Chdir(repo.Dir)
 58→
 59→		ctx := context.Background()
 60→		b.ResetTimer()
 61→		for i := range b.N {
 62→			// Re-create the shadow branch state for each iteration so we always
 63→			// measure the first-checkpoint path (which runs collectChangedFiles).
 64→			// We use a unique session ID per iteration to get a fresh shadow branch.
 65→			sid := fmt.Sprintf("bench-first-%d", i)
 66→			_, writeErr := repo.Store.WriteTemporary(ctx, checkpoint.WriteTemporaryOptions{
 67→				SessionID:         sid,
 68→				BaseCommit:        repo.HeadHash,
 69→				WorktreeID:        repo.WorktreeID,
 70→				ModifiedFiles:     []string{"src/file_000.go", "src/file_001.go", "src/file_002.go"},
 71→				MetadataDir:       metadataDir,
 72→				MetadataDirAbs:    metadataDirAbs,
 73→				CommitMessage:     "benchmark checkpoint",
 74→				AuthorName:        "Bench",
 75→				AuthorEmail:       "bench@test.com",
 76→				IsFirstCheckpoint: true,
 77→			})
 78→			if writeErr != nil {
 79→				b.Fatalf("WriteTemporary: %v", writeErr)
 80→			}
 81→		}
 82→	}
 83→}
 84→
 85→// benchWriteTemporaryIncremental benchmarks subsequent checkpoints (not the first).
 86→// These skip collectChangedFiles and only process the provided file lists.
 87→func benchWriteTemporaryIncremental(modified, newFiles, deleted int) func(*testing.B) {
 88→	return func(b *testing.B) {
 89→		repo := benchutil.NewBenchRepo(b, benchutil.RepoOpts{
 90→			FileCount:     max(modified+newFiles, 10),
 91→			FileSizeLines: 100,
 92→		})
 93→		sessionID := repo.CreateSessionState(b, benchutil.SessionOpts{})
 94→
 95→		// Seed one checkpoint so subsequent ones are not IsFirstCheckpoint
 96→		repo.SeedShadowBranch(b, sessionID, 1, 3)
 97→
 98→		// Prepare file lists
 99→		modifiedFiles := make([]string, 0, modified)
100→		for i := range modified {
101→			name := fmt.Sprintf("src/file_%03d.go", i)
102→			repo.WriteFile(b, name, benchutil.GenerateGoFile(8000+i, 100))
103→			modifiedFiles = append(modifiedFiles, name)
104→		}
105→		newFileList := make([]string, 0, newFiles)
106→		for i := range newFiles {
107→			name := fmt.Sprintf("src/new_%03d.go", i)
108→			repo.WriteFile(b, name, benchutil.GenerateGoFile(7000+i, 100))
109→			newFileList = append(newFileList, name)
110→		}
111→		deletedFiles := make([]string, 0, deleted)
112→		for i := range deleted {
113→			deletedFiles = append(deletedFiles, fmt.Sprintf("src/file_%03d.go", modified+newFiles+i))
114→		}
115→
116→		metadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
117→		metadataDirAbs := filepath.Join(repo.Dir, metadataDir)
118→		if err := os.MkdirAll(metadataDirAbs, 0o750); err != nil {
119→			b.Fatalf("mkdir metadata: %v", err)
120→		}
121→
122→		b.Chdir(repo.Dir)
123→
124→		ctx := context.Background()
125→		b.ResetTimer()
126→		for range b.N {
127→			_, writeErr := repo.Store.WriteTemporary(ctx, checkpoint.WriteTemporaryOptions{
