// seedCheckpoints writes N checkpoints with the given transcript size to the metadata branch.
// Each checkpoint gets a unique transcript (different seed) so git cannot deduplicate
// identical blobs — matching real-world behavior where every session is different.
func seedCheckpoints(t *testing.T, store *checkpoint.GitStore, count, transcriptSize int) {
	t.Helper()

	ctx := context.Background()

	for i := range count {
		transcript := generatePerfJSONL(transcriptSize, i)

		cpID, err := id.Generate()
		if err != nil {
			t.Fatalf("id.Generate: %v", err)
		}
		err = store.WriteCommitted(ctx, checkpoint.WriteCommittedOptions{
			CheckpointID:     cpID,
			SessionID:        fmt.Sprintf("perf-session-%d", i),
			Agent:            agent.AgentTypeClaudeCode,
			Transcript:       transcript,
			Prompts:          []string{"Implement the feature"},
			CheckpointsCount: 1,
			AuthorName:       "Push Perf Test",
			AuthorEmail:      "test@example.com",
		})
		if err != nil {
			t.Fatalf("WriteCommitted checkpoint %d: %v", i, err)
		}
	}
}

// generatePerfJSONL creates a realistic JSONL transcript of the given approximate size.
// The seed parameter varies the content so each checkpoint gets a unique transcript,
// preventing git from deduplicating identical blobs across checkpoints.
func generatePerfJSONL(targetSize, seed int) []byte {
	var buf strings.Builder
	// Varied templates with different message types and content patterns.
	// The seed offsets IDs and rotates content to make each transcript unique.
	templates := []string{
		`{"type":"human","message":{"id":"msg_%06d","content":"Please implement the feature for handling user authentication in module %d"}}`,
		`{"type":"assistant","message":{"id":"msg_%06d","content":"I'll implement the authentication feature. Let me start by creating the middleware and setting up the routes for session %d...","model":"claude-sonnet-4-5-20250514","stop_reason":"end_turn","usage":{"input_tokens":%d,"output_tokens":%d}}}`,
		`{"type":"tool_use","id":"toolu_%06d","name":"Write","input":{"file_path":"/src/auth/handler_%d.go","content":"package auth\n\nimport \"net/http\"\n\nfunc Handler%d(w http.ResponseWriter, r *http.Request) {\n\tw.WriteHeader(http.StatusOK)\n}"},"output":"File written successfully"}`,
		`{"type":"tool_result","id":"toolu_%06d","content":"Successfully wrote %d bytes to /src/auth/handler_%d.go"}`,
		`{"type":"tool_use","id":"toolu_%06d","name":"Read","input":{"file_path":"/src/service/worker_%d.go"},"output":"package service\n\ntype Worker%d struct {\n\tID   int\n\tName string\n}\n\nfunc (w *Worker%d) Process() error {\n\treturn nil\n}"}`,
		`{"type":"assistant","message":{"id":"msg_%06d","content":"Looking at the existing code in worker_%d.go, I can see the Worker struct. Let me now update the handler to integrate with this service layer and add proper error handling for edge case %d...","model":"claude-sonnet-4-5-20250514","stop_reason":"end_turn","usage":{"input_tokens":%d,"output_tokens":%d}}}`,
		`{"type":"tool_use","id":"toolu_%06d","name":"Bash","input":{"command":"go test ./src/auth/... -count=1 -run TestHandler%d"},"output":"ok  \tsrc/auth\t0.%03ds\n--- PASS: TestHandler%d"}`,
		`{"type":"tool_result","id":"toolu_%06d","content":"All %d tests passed in module %d"}`,
	}

	base := seed * 100000 // large offset so content differs substantially between seeds
