// seedCheckpoints writes N checkpoints with the given transcript size to the metadata branch.
// Each checkpoint gets a unique transcript (different seed) so git cannot deduplicate
// identical blobs — matching real-world behavior where every session is different.
// Returns the total time spent seeding.
func seedCheckpoints(t *testing.T, store *checkpoint.GitStore, count, transcriptSize int) time.Duration {
	t.Helper()

	ctx := context.Background()
	start := time.Now()

	// Log progress for large scenarios.
	logInterval := progressInterval(count, transcriptSize)

	for i := range count {
		if logInterval > 0 && i > 0 && i%logInterval == 0 {
			t.Logf("  seeding: %d/%d checkpoints (%s elapsed)", i, count, time.Since(start).Round(time.Millisecond))
		}

		transcript := generatePerfJSONL(transcriptSize, i)

		cpID, err := id.Generate()
		if err != nil {
			t.Fatalf("id.Generate: %v", err)
		}
		err = store.WriteCommitted(ctx, checkpoint.WriteCommittedOptions{
			CheckpointID:     cpID,
			SessionID:        fmt.Sprintf("perf-session-%d", i),
			Agent:            agent.AgentTypeClaudeCode,
			Transcript:       transcript,
			Prompts:          []string{"Implement the feature"},
			CheckpointsCount: 1,
			AuthorName:       "Push Perf Test",
			AuthorEmail:      "test@example.com",
		})
		if err != nil {
			t.Fatalf("WriteCommitted checkpoint %d: %v", i, err)
		}
	}

	return time.Since(start)
}

// progressInterval returns how often to log seeding progress, or 0 to skip.
func progressInterval(count, transcriptSize int) int {
	totalBytes := int64(count) * int64(transcriptSize)
	switch {
	case totalBytes > 500*1024*1024: // >500MB total
		return 5
	case totalBytes > 100*1024*1024: // >100MB total
		return 10
	case totalBytes > 20*1024*1024: // >20MB total
		return 25
	default:
		return 0 // no progress logging for small scenarios
	}
}

// generatePerfJSONL creates a realistic JSONL transcript of the given approximate size.
// The seed parameter varies the content so each checkpoint gets a unique transcript,
// preventing git from deduplicating identical blobs across checkpoints.
func generatePerfJSONL(targetSize, seed int) []byte {
	var buf strings.Builder
	base := seed * 100000 // large offset so content differs substantially between seeds
	i := 0
	for buf.Len() < targetSize {
		n := base + i
		var line string
		switch i % 8 {
		case 0:
			line = fmt.Sprintf(`{"type":"human","message":{"id":"msg_%06d","content":"Please implement the feature for handling user authentication in module %d"}}`, n, n)
		case 1:
			line = fmt.Sprintf(`{"type":"assistant","message":{"id":"msg_%06d","content":"I'll implement the authentication feature for session %d. Let me start by creating the middleware and setting up the routes...","model":"claude-sonnet-4-5-20250514","stop_reason":"end_turn","usage":{"input_tokens":%d,"output_tokens":%d}}}`, n, n, 1200+n%5000, 4500+n%8000)
		case 2:
			line = fmt.Sprintf(`{"type":"tool_use","id":"toolu_%06d","name":"Write","input":{"file_path":"/src/auth/handler_%d.go","content":"package auth\n\nimport \"net/http\"\n\nfunc Handler%d(w http.ResponseWriter, r *http.Request) {\n\tw.WriteHeader(http.StatusOK)\n}"},"output":"File written successfully"}`, n, n, n)
		case 3:
			line = fmt.Sprintf(`{"type":"tool_result","id":"toolu_%06d","content":"Successfully wrote %d bytes to /src/auth/handler_%d.go"}`, n, 200+n%2000, n)
		case 4:
			line = fmt.Sprintf(`{"type":"tool_use","id":"toolu_%06d","name":"Read","input":{"file_path":"/src/service/worker_%d.go"},"output":"package service\n\ntype Worker%d struct {\n\tID int\n\tName string\n}\n\nfunc (w *Worker%d) Process() error { return nil }"}`, n, n, n, n)
		case 5:
			line = fmt.Sprintf(`{"type":"assistant","message":{"id":"msg_%06d","content":"Looking at the existing code in worker_%d.go, I can see the Worker struct. Let me update the handler to integrate with the service layer and add error handling for edge case %d...","model":"claude-sonnet-4-5-20250514","stop_reason":"end_turn","usage":{"input_tokens":%d,"output_tokens":%d}}}`, n, n, n, 2400+n%6000, 5200+n%9000)
		case 6:
			line = fmt.Sprintf(`{"type":"tool_use","id":"toolu_%06d","name":"Bash","input":{"command":"go test ./src/auth/... -count=1 -run TestHandler%d"},"output":"ok  \tsrc/auth\t0.%03ds\n--- PASS: TestHandler%d"}`, n, n, n%999, n)
		case 7:
			line = fmt.Sprintf(`{"type":"tool_result","id":"toolu_%06d","content":"All %d tests passed in module %d with no regressions"}`, n, 3+n%50, n)
		}
		buf.WriteString(line)
		buf.WriteByte('\n')
		i++
	}
	return []byte(buf.String())
}

// addRemote adds a git remote to the local repo.
func addRemote(t *testing.T, dir, url string) {
	t.Helper()

	cmd := exec.Command("git", "remote", "add", "origin", url)
	cmd.Dir = dir
	out, err := cmd.CombinedOutput()
	if err != nil {
		// Remote may already exist from a previous call; try set-url instead.
		cmd2 := exec.Command("git", "remote", "set-url", "origin", url)
		cmd2.Dir = dir
		out2, err2 := cmd2.CombinedOutput()
		if err2 != nil {
			t.Fatalf("git remote add/set-url failed: %v\n%s\n%s", err, out, out2)
		}
	}
}

// runGitGC runs git gc to pack objects (simulates a realistic repo state).
func runGitGC(t *testing.T, dir string) {
	t.Helper()

	cmd := exec.Command("git", "gc", "--aggressive", "--prune=now")
	cmd.Dir = dir
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("git gc: %v\n%s", err, out)
	}
}

// measureRepoSize returns the loose object size, pack size, and total .git size in KB.
func measureRepoSize(t *testing.T, dir string) (looseKB, packKB, totalKB int64) {
	t.Helper()

	// Parse git count-objects -v for loose/pack sizes.
	cmd := exec.Command("git", "count-objects", "-v")
	cmd.Dir = dir
	out, err := cmd.Output()
	if err != nil {
		t.Fatalf("git count-objects: %v", err)
	}

	for _, line := range strings.Split(string(out), "\n") {
		parts := strings.SplitN(line, ": ", 2)
		if len(parts) != 2 {
			continue
		}
		key := strings.TrimSpace(parts[0])
		val := strings.TrimSpace(parts[1])
		switch key {
		case "size": // loose object size in KB
			v, _ := strconv.ParseInt(val, 10, 64)
			looseKB = v
		case "size-pack": // pack size in KB
			v, _ := strconv.ParseInt(val, 10, 64)
			packKB = v
		}
	}

	// Total .git directory size via du.
	duCmd := exec.Command("du", "-sk", filepath.Join(dir, ".git"))
	duOut, duErr := duCmd.Output()
	if duErr == nil {
		parts := strings.Fields(string(duOut))
		if len(parts) > 0 {
			v, _ := strconv.ParseInt(parts[0], 10, 64)
			totalKB = v
		}
	}

	return looseKB, packKB, totalKB
}

// timePush times a regular (fast-forward) git push and returns the wall-clock duration.
func timePush(t *testing.T, dir, remote, branch string) time.Duration {
	t.Helper()
	return doTimedPush(t, dir, "git", "push", remote, "refs/heads/"+branch)
}

// timeForcePush times a force push and returns the wall-clock duration.
// Used when each subtest has independent history unrelated to what's already on the remote.
func timeForcePush(t *testing.T, dir, remote, branch string) time.Duration {
	t.Helper()
	return doTimedPush(t, dir, "git", "push", "--force", remote, "refs/heads/"+branch)
}

// doTimedPush runs a git push command and returns its wall-clock duration.
func doTimedPush(t *testing.T, dir string, args ...string) time.Duration {
	t.Helper()

	var stderr bytes.Buffer
	cmd := exec.Command(args[0], args[1:]...)
	cmd.Dir = dir
	cmd.Stderr = &stderr

	start := time.Now()
	err := cmd.Run()
	dur := time.Since(start)

	if err != nil {
		t.Fatalf("git push failed (%s): %v\n%s", dur, err, stderr.String())
	}

	return dur
}

