	_, incrBytes := seedCheckpoints(t, store, src, 1, transcriptSize)
	timeGitGC(t, dir)

	_, _, totalKB := measureRepoSize(t, dir)

	incDur := timePush(t, dir, "origin", "entire/checkpoints/v1")

