// parseTrace2Phases extracts timing phases from GIT_TRACE2_EVENT JSON lines.
// It collects region_leave events (with durations) and child process durations.
func parseTrace2Phases(t *testing.T, data []byte) []pushPhase {
	t.Helper()

	var phases []pushPhase
	childNames := make(map[int]string)

	for _, line := range bytes.Split(data, []byte("\n")) {
		if len(line) == 0 {
			continue
		}
		var ev trace2Event
		if err := json.Unmarshal(line, &ev); err != nil {
			continue
		}

		switch ev.Event {
		case "child_start":
			name := ev.ChildClass
			if name == "" && len(ev.Argv) > 0 {
				// Build name from non-flag argv elements.
				var parts []string
				for _, arg := range ev.Argv {
					if strings.HasPrefix(arg, "-") {
						break
					}
					parts = append(parts, filepath.Base(arg))
				}
				name = strings.Join(parts, " ")
			}
			childNames[ev.ChildID] = name

		case "child_exit":
			if ev.TRel > 0.001 { // skip <1ms noise
				name := childNames[ev.ChildID]
				if name == "" {
					name = fmt.Sprintf("child[%d]", ev.ChildID)
				}
				dur := time.Duration(ev.TRel * float64(time.Second))
				phases = append(phases, pushPhase{
					name:     fmt.Sprintf("child: %s", name),
					duration: dur,
				})
			}

		case "region_leave":
			if ev.TRel > 0.001 { // skip <1ms noise
				name := ev.Category
				if ev.Label != "" {
					name += "/" + ev.Label
				}
				indent := strings.Repeat("  ", ev.Nesting)
				dur := time.Duration(ev.TRel * float64(time.Second))
				phases = append(phases, pushPhase{
					name:     indent + name,
					duration: dur,
				})
			}
		}
	}

	return phases
}

